uint64_t SegmentImpl::doc_count(const IndexFilter::Ptr filter) {
  uint64_t doc_count = doc_ids_.size();
  if (filter) {
    for (const auto &doc_id : doc_ids_) {
      if (filter->is_filtered(doc_id)) {
        doc_count--;
      }
    }
  }

  return doc_count;
}

